var rows = $input.all();
var data = rows.map(function(r) {
  return {
    name: String(r.json['Guest Name'] || 'Unknown'),
    email: String(r.json['From Email'] || ''),
    checkIn: String(r.json['Check-In'] || ''),
    checkOut: String(r.json['Check-Out'] || ''),
    nights: String(r.json['Nights'] || ''),
    summary: String(r.json['Summary'] || ''),
    status: String(r.json['Status'] || 'Pending')
  };
}).filter(function(r) { return r.checkIn && r.checkOut; });

var total    = rows.length;
var pending  = data.filter(function(r) { return r.status === 'Pending';  }).length;
var accepted = data.filter(function(r) { return r.status === 'Accepted'; }).length;
var declined = data.filter(function(r) { return r.status === 'Declined'; }).length;

var p = [];
p.push('<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">');
p.push('<meta name="viewport" content="width=device-width,initial-scale=1">');
p.push('<title>WG-Gesucht Requests</title>');
p.push('<link href="https://cdn.jsdelivr.net/npm/vis-timeline@7.7.3/dist/vis-timeline-graph2d.min.css" rel="stylesheet">');
p.push('<style>');
p.push('*{box-sizing:border-box;margin:0;padding:0}');
p.push('body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#f8f9fa;padding:24px;color:#333}');
p.push('h1{font-size:22px;font-weight:600;margin-bottom:20px}');
p.push('.stats{display:flex;gap:12px;margin-bottom:24px;flex-wrap:wrap}');
p.push('.stat{background:white;padding:16px 20px;border-radius:10px;box-shadow:0 1px 4px rgba(0,0,0,.08);min-width:110px}');
p.push('.stat-value{font-size:28px;font-weight:700}');
p.push('.stat-label{font-size:12px;color:#777;margin-top:2px;text-transform:uppercase;letter-spacing:.5px}');
p.push('.stat.pending .stat-value{color:#f59e0b}');
p.push('.stat.accepted .stat-value{color:#10b981}');
p.push('.stat.declined .stat-value{color:#ef4444}');
p.push('.wrap{background:white;border-radius:10px;box-shadow:0 1px 4px rgba(0,0,0,.08);padding:16px}');
p.push('.legend{display:flex;gap:16px;margin-bottom:16px;font-size:13px}');
p.push('.legend-item{display:flex;align-items:center;gap:6px}');
p.push('.legend-dot{width:12px;height:12px;border-radius:3px}');
p.push('.vis-item.pending{background:#fef3c7!important;border-color:#f59e0b!important;color:#92400e!important}');
p.push('.vis-item.accepted{background:#d1fae5!important;border-color:#10b981!important;color:#064e3b!important}');
p.push('.vis-item.declined{background:#fee2e2!important;border-color:#ef4444!important;color:#7f1d1d!important}');
p.push('.vis-item.vis-selected{border-width:2px}');
p.push('.empty{text-align:center;padding:40px;color:#aaa}');
p.push('</style></head><body>');
p.push('<h1>WG-Gesucht Rental Requests</h1>');
p.push('<div class="stats">');
p.push('<div class="stat"><div class="stat-value">' + total + '</div><div class="stat-label">Total</div></div>');
p.push('<div class="stat pending"><div class="stat-value">' + pending + '</div><div class="stat-label">Pending</div></div>');
p.push('<div class="stat accepted"><div class="stat-value">' + accepted + '</div><div class="stat-label">Accepted</div></div>');
p.push('<div class="stat declined"><div class="stat-value">' + declined + '</div><div class="stat-label">Declined</div></div>');
p.push('</div>');
p.push('<div class="wrap">');
p.push('<div class="legend">');
p.push('<div class="legend-item"><div class="legend-dot" style="background:#fef3c7;border:2px solid #f59e0b"></div>Pending</div>');
p.push('<div class="legend-item"><div class="legend-dot" style="background:#d1fae5;border:2px solid #10b981"></div>Accepted</div>');
p.push('<div class="legend-item"><div class="legend-dot" style="background:#fee2e2;border:2px solid #ef4444"></div>Declined</div>');
p.push('</div>');
p.push('<div id="vis"></div>');
p.push('</div>');
p.push('<script src="https://cdn.jsdelivr.net/npm/vis-timeline@7.7.3/dist/vis-timeline-graph2d.min.js"></script>');
p.push('<script>');
p.push('var DATA = ' + JSON.stringify(data) + ';');
p.push('if (!DATA.length) {');
p.push('  document.getElementById("vis").innerHTML = "<div class=\"empty\">No requests with valid dates yet. Check that Check-In and Check-Out columns are filled.</div>";');
p.push('} else {');
p.push('  var items = new vis.DataSet(DATA.map(function(r, i) {');
p.push('    return {');
p.push('      id: i,');
p.push('      content: r.name + (r.nights ? " (" + r.nights + "n)" : ""),');
p.push('      start: r.checkIn,');
p.push('      end: r.checkOut,');
p.push('      className: r.status.toLowerCase(),');
p.push('      title: "<b>" + r.name + "</b><br>" + r.email + "<br>" + r.checkIn + " \u2192 " + r.checkOut + (r.nights ? " (" + r.nights + " nights)" : "") + "<br><em>" + r.summary + "</em>"');
p.push('    };');
p.push('  }));');
p.push('  new vis.Timeline(document.getElementById("vis"), items, {');
p.push('    type: "range",');
p.push('    orientation: { axis: "top" },');
p.push('    stack: true,');
p.push('    moveable: true,');
p.push('    zoomable: true,');
p.push('    selectable: false,');
p.push('    tooltip: { followMouse: true, delay: 200 }');
p.push('  });');
p.push('}');
p.push('</script></body></html>');

return [{ json: { html: p.join('\n') } }];
